"""Step 2026-10-17 (Stakeholder Analysis): link the stakeholder tool in the hub (index.html) from the start. Every anchor must match once.
    python3 tests/build/patch_hub_stakeholders.py index.html
Then serve the platform folder and run tests/build/demo_stakeholders.py, which fills DEMO_RES.stakeholders from the hub's own reading of the
example (until then a placeholder with st "none" stands in). The other adapters (pestleAd, swotAd, qtAd …) are left as they are, so the snapshots
the hub reads for the other tools do not change. The tool goes into Audit & Improvement with the rest of the toolbox, next to SWOT and PESTLE
(16 rows there, 39 in all): it is built on the toolbox engine and feeds SWOT and PESTLE. The toolbox is now complete, so the grouped "coming
soon" toolbox entry (citbox) is removed from SOON (only the Egypt award stays under addition)."""
import sys, os

HERE = os.path.dirname(os.path.abspath(__file__))
path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "..", "..", "index.html")
s = open(path, encoding="utf-8").read()
if 'stakeholders: "./modules/stakeholders.html"' in s:
    print("Stakeholder Analysis already linked; nothing to do"); sys.exit(0)


def rep(old, new):
    global s
    n = s.count(old)
    assert n == 1, (n, old[:100])
    s = s.replace(old, new)


# 1. URL
rep('  pestle:   "./modules/pestle.html"\n};', '  pestle:   "./modules/pestle.html",\n  stakeholders: "./modules/stakeholders.html"\n};')
